def remplir_codes_presence(apps, schema_editor):
    # Un UUID distinct par candidature existante (un default unique serait identique pour toutes les lignes)
    Candidature = apps.get_model('login_app', 'Candidature')
    for cand in Candidature.objects.filter(code_presence__isnull=True):
        cand.code_presence = uuid.uuid4()
        cand.save(update_fields=['code_presence'])


